"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6620"],{4869(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"changelog/product/14-10","title":"What\'s new in 14.10 - October 2014","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/changelog/product/14-10.md","sourceDirName":"changelog/product","slug":"/changelog/product/14-10","permalink":"/personal-av-docs/docs/changelog/product/14-10","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/changelog/product/14-10.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"What\'s new in 14.10 - October 2014","sidebar_label":"What\'s new in 14.10 - October 2014","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/whatsnew/14-10","format":"md"}}'),i=n(4848),o=n(8453);let s={title:"What's new in 14.10 - October 2014",sidebar_label:"What's new in 14.10 - October 2014",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/whatsnew/14-10",format:"md"},r,l={},c=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/alms/whatsnew/14-10",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"What's new in 14.10 - October 2014\nNew features & Improvements\nInitializing Table Of Contents...\nDashboard\nFailover Status widget\nIn case you have high business continuity expectations and want to ensure you have a backup to your primary ISP, you have the possibility to use the AirLink Gateway to this purpose. In that case, your network can be setup as follows:\nTo take the most advantage of such backup setup, you need a way to monitor the states of your backed up sites.\nA new widget Failover Status is available in the Dashboard to this purpose and displays the distribution of devices using the backup connection vs primary connection.\nThis display is based on the use of Reliable Static Route (RSR) capability of AirLink devices. As soon as the primary ISP on a site falls, the backup will be used and the Failover Status widget will be updated accordingly.\nRegister\nNew module types available\nSL8 series: additional flavors of SL808x flavors are now available including SL808xBT, TR and BTR.\nQ2698 is now available in Beta version in AirVantage\nBeta version means that it has the FW and application updgrade capabilities and minimal set of monitoring parameters, to enable customer testing.\nEnhanced display for AirPrime modules\nAirPrime modules are now displayed by families which provides a better overview of the AirVantage support for each series directly from the Register activity.\nAutomatic label creation\nWant to add one or more label(s) as part of multiple system registration? You don\u2019t need to create the label prior to the import any more. The label(s) are automatically created in an add label operation if not existing yet.\nImport with initial configuration\nThe initial configuration is the capability to predefine a configuration (install a firmware, configure communication and/or apply a template) for one or multiple systems.\nThe initial configuration that can be applied on a fleet has been reworked. When applying an initial configuration to multiple systems, each system will now follow its configuration flow independently. The initial configuration for a fleet is therefore far more efficient than it previously was.\nInventory\nSystem activation\nIn case your system in inventory is linked to a wireless subscription, when activating your system, we are automatically proposing as an option to activate the subscription.\nThis is valid for all carriers for which we have a carrier integration. For more details on the carriers that are elligible to this capability, please check section\nAdditional information on subscription management\n.\nIf you have a need for activating systems, you might find interesting to add to your start page the system activation widget that will display to you the list of systems within your company that can be activated.\nMonitor\nUpgrade your Verizon GX440 fleet\nTo help you in the upgrade of your GX440 Verizon to the latest version, we developped a specific One-click tool based on AirVantage Management Services to facilitate the management of the upgrades for you.\nThis is an efficient add-on to AirLink Management Services, as all the different upgrade hops mentionned in the ALEOS upgrade path will be automatically handled for you.\nWith this tool you will be to view all the GX400 Verizon that you have within your company, based on their current FW version and upgrade them to 4.3.4 in one single click. If you want to test it first on a subset of system, we allow that using a label that would have been previously applied in AirVantage.\nFor more information, you can refer to the dedicated page:\nUpgrade your GX440 Verizon\nApply a different setting value per system\nWhen configuring your systems, for specific settings, you may require to specify a different value for each of the system of your fleet. This is especially the case for system names, for sensitive information such as passwords, etc\u2026\nTo this purpose, you can now use the new Monitor functionality to apply setting by CSV. You will first need to state how you want to identify the systems on which the operation will be triggered. You can identify them using one among:\nName\nSerial Number\nIMEI\nMAC address\nICCID/ESN\nIMSI/MIN\nIP address\nNext step is to select in the configuration model the setting for which you want to apply a different value. And finally, the corresponding csv file.\nThe .csv file will therefore need to contain a list of identifiers and a list of value for the above selected setting.\nThis feature will be especially interesting for setting system names, sensitive information such as passwords, etc\u2026 You can find an example of use for setting different names per system\nhere\n.\nChange your AceManager and M3DA password remotely\nThis feature will be available for LinALEOS Gateways from 4.4.0 version and onwards.\nDevelop\nDownload firmware and application binaries\nFor each new application or firmware recently released, you now have the capability to download the application or firmware package including binaries.\nAs a consequence, you can now use AirVantage as an application repository to store your application binaries and be able to retrieve them at any time.\nGeneral\nNew design for grids\nThe design for grid-type widgets and for the main grids has been reworked for better consistency with the overall portal design. It brings clarity and is more readable for the user.\nIn the same vein of improvements, we condensated the font in main grids to display more in the same space.\nEnhanced capabilites for operations\nNoticed that you just launched a campaign including a system that shouldn\u2019t have been? You now have the capability not only to cancel one whole operation, but you can also cancel on a system by system basis. The task status bar will be updated accordingly.\nCancelling an operation on one system still permits you to cancel the whole operation afterwards if necessary. In that case, the cancel on the whole operation will cancel the remaining pending tasks.\nThis capability is available on all kind of operations, including those launched on subscriptions and gateways.\nWant to view all operations for which you had at least one failure? A new Final Status filtering criteria is now available to you in the operations section both in Monitor and Inventory.\nFiltering by Final Status will only display the operations that are finished in the selected status (SUCCESS, FAILURE or CANCELLED) are displayed:\nSUCCESS : all tasks are SUCCESS\nFAILURE : at least one task is FAILURE\nCANCELLED : at least one task is CANCELLED\nYou can now benefit of more detailed operation notifications when an operation finishes.\nTo permit a quicker analysis, the status of the operation is now directly visible in the email title of the notification. Also when launching the operation on one single system, the notification title will also include the system name.\nSame kind of behavior with operations on entities such as gateways or subscriptions for which we will display the entity identifier."})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);